import { useEffect, useState } from "react";
import { getChildren, addAttendance } from "../api/api";

function Attendance() {
  const [children, setChildren] = useState([]);
  const [child_id, setChildId] = useState("");
  const [checkIn, setCheckIn] = useState("");
  const [checkOut, setCheckOut] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    getChildren().then(res => setChildren(res.data));
  }, []);

  const handleSubmit = () => {
    addAttendance({
      child_id,
      check_in: checkIn,
      check_out: checkOut,
      date
    }).then(() => alert("Attendance saved"));
  };

  return (
    <div>
      <h2>Attendance</h2>

      <select onChange={e => setChildId(e.target.value)}>
        <option>Select Child</option>
        {children.map(c => (
          <option key={c.id} value={c.id}>{c.name}</option>
        ))}
      </select>

      <input type="time" onChange={e => setCheckIn(e.target.value)} />
      <input type="time" onChange={e => setCheckOut(e.target.value)} />
      <input type="date" onChange={e => setDate(e.target.value)} />

      <button onClick={handleSubmit}>Save</button>
    </div>
  );
}

export default Attendance;
